```java
import java.sql.*;

public class JdbcDemo {
    public static void main(String[] args) {
        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;
        try {
            // 第一步：加载驱动（JDBC 4.0 后可省略）
            Class.forName("com.mysql.cj.jdbc.Driver");

            // 第二步：建立连接
            String url = "jdbc:mysql://localhost:3306/School"
                       + "?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8";
            conn = DriverManager.getConnection(url, "root", "123456");

            // 第三步：创建 SQL 执行对象（用 PreparedStatement 防止 SQL 注入）
            String sql = "SELECT Sno, Sname, Sage FROM Student WHERE Sage > ?";
            pstmt = conn.prepareStatement(sql);
            pstmt.setInt(1, 18);                 // 给第 1 个 ? 赋值

            // 第四步：执行 SQL，得到结果集
            rs = pstmt.executeQuery();

            // 第五步：处理结果集
            while (rs.next()) {
                String sno = rs.getString("Sno");
                String sname = rs.getString("Sname");
                int sage = rs.getInt("Sage");
                System.out.println(sno + "\t" + sname + "\t" + sage);
            }
        } catch (ClassNotFoundException | SQLException e) {
            e.printStackTrace();
        } finally {
            // 第六步：释放资源（顺序：ResultSet → Statement → Connection）
            try { if (rs != null) rs.close(); } catch (SQLException e) { e.printStackTrace(); }
            try { if (pstmt != null) pstmt.close(); } catch (SQLException e) { e.printStackTrace(); }
            try { if (conn != null) conn.close(); } catch (SQLException e) { e.printStackTrace(); }
        }
    }
}
```

| 对比项 | `Statement` | `PreparedStatement` |
|---|---|---|
| SQL 是否预编译 | 否 | **是**（性能更好） |
| 参数设置 | 字符串拼接 | `setXxx()` 方法 |
| **SQL 注入** | **存在风险** | **可有效防止** |
| 可读性 | 拼接长 SQL 时很差 | 好 |
| 推荐程度 | 不推荐 | **推荐** |

**SQL 注入示例**（危险写法）：

```java
// 错误示范：字符串拼接会带来 SQL 注入风险
String name = "张三' OR '1'='1";
String sql = "SELECT * FROM Student WHERE Sname = '" + name + "'";
// 实际执行的 SQL 变成：
// SELECT * FROM Student WHERE Sname = '张三' OR '1'='1'
// 条件永远为真，会返回全部学生数据！
```

```java
// 调用带参数的存储过程
CallableStatement cstmt = conn.prepareCall("{CALL pro_get_emp_dept(?, ?)}");
cstmt.setString(1, "陈明");                              // IN 参数
cstmt.registerOutParameter(2, Types.VARCHAR);            // 注册 OUT 参数
cstmt.execute();
String deptName = cstmt.getString(2);                    // 获取输出值
System.out.println("部门名称：" + deptName);
```

> **可能延伸考点**：JDBC 编程步骤、`Statement` 与 `PreparedStatement` 的区别、SQL 注入的防范。

